<?php declare(strict_types=1); ?>
<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Required attention</span><h2>Purchase-order commitments</h2></div><a href="<?= h(root_url('supplier-portal/index.php?tab=orders')) ?>">Open orders</a></header><div class="record-list"><?php foreach(array_slice($pos,0,5) as $po): ?><article class="record-card"><header><div><strong><?= h($po['po_number']) ?></strong><small><?= h(data_company_name($po['company_id'])) ?> · Expected <?= h(date_us($po['expected_date'])) ?></small></div><span class="status <?= h($po['status']) ?>"><?= h(status_label($po['status'])) ?></span></header><p><?= money($po['total_amount']) ?> authorized order value.</p></article><?php endforeach; ?><?php if(!$pos): ?><div class="empty">No purchase orders are authorized for this supplier account.</div><?php endif; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Communication</span><h2>Messages requiring response</h2></div><a href="<?= h(root_url('supplier-portal/index.php?tab=messages')) ?>">Open messages</a></header><div class="record-list"><?php foreach(array_slice($messages,0,5) as $message): ?><article class="record-card"><header><div><strong><?= h($message['subject']) ?></strong><small><?= h(status_label($message['entity_type'])) ?> #<?= (int)$message['entity_id'] ?> · <?= h(date_us($message['created_at'],true)) ?></small></div><span class="status <?= h($message['status']) ?>"><?= h(status_label($message['status'])) ?></span></header><p><?= h($message['message_body']) ?></p></article><?php endforeach; ?><?php if(!$messages): ?><div class="empty">No supplier-visible messages.</div><?php endif; ?></div></section></div>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Payment transparency</span><h2>Remittance advice</h2></div><span class="panel-meta"><?= count($remittances) ?> settlement record(s)</span></header><div class="table-wrap"><table><thead><tr><th>Remittance</th><th>Payment date</th><th>Settlement</th><th class="numeric">Gross</th><th class="numeric">Credits</th><th class="numeric">Net paid</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($remittances,0,10) as$r): ?><tr><td><strong><?= h($r['remittance_number']) ?></strong><small><?= h($r['payment_reference']) ?></small></td><td><?= h(date_us($r['payment_date'])) ?></td><td><?= h($r['settlement_reference']) ?></td><td class="numeric"><?= money($r['gross_amount']) ?></td><td class="numeric"><?= money($r['credit_amount']) ?></td><td class="numeric"><strong><?= money($r['net_amount']) ?></strong></td><td><span class="status <?= h($r['delivery_status']) ?>"><?= h(status_label($r['delivery_status'])) ?></span></td></tr><?php endforeach; ?><?php if(!$remittances): ?><tr><td colspan="7"><div class="empty">No settled remittance records are available.</div></td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Recent activity</span><h2>Submitted collaboration records</h2></div></header><div class="table-wrap"><table><thead><tr><th>Type</th><th>Reference</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach(array_slice(array_merge(array_map(fn($r)=>['type'=>'PO response','ref'=>$r['response_number'],'status'=>$r['status'],'created'=>$r['created_at']],$responses),array_map(fn($r)=>['type'=>'ASN','ref'=>$r['asn_number'],'status'=>$r['status'],'created'=>$r['created_at']],$asns),array_map(fn($r)=>['type'=>'Invoice','ref'=>$r['invoice_number'],'status'=>$r['status'],'created'=>$r['created_at']],$invoices),array_map(fn($r)=>['type'=>'Document','ref'=>$r['title'],'status'=>$r['status'],'created'=>$r['created_at']],$documents)),0,10) as $row): ?><tr><td><?= h($row['type']) ?></td><td><strong><?= h($row['ref']) ?></strong></td><td><span class="status <?= h($row['status']) ?>"><?= h(status_label($row['status'])) ?></span></td><td><?= h(date_us($row['created'],true)) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
